import * as THREE from 'three/webgpu';
import { color, float, mix, uv, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Object3D();
  group.name = 'feature-triptych';
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const cardW = 1.5, cardH = 1.9, gap = 0.25;
  const rowTotal = cardW * 3 + gap * 2;
  const startX = -rowTotal / 2 + cardW / 2;

  const cardsData = [
    { glyph: '01', title: 'In-House Calibre', body: 'Every movement is designed, machined, and finished under one roof.' },
    { glyph: '02', title: 'Five-Year Guarantee', body: 'Each piece is serviced free of charge for five years from delivery.' },
    { glyph: '03', title: 'Hand-Finished Dials', body: 'Guilloche cut on a 1912 rose engine, one dial at a time.' }
  ];

  const disposables = [];
  const timelines = [];
  const cardObjects = [];

  const cardGeo = new THREE.PlaneGeometry(cardW, cardH, 1, 1);
  disposables.push(cardGeo);
  const discGeo = new THREE.CylinderGeometry(0.2, 0.2, 0.05, 32);
  disposables.push(discGeo);

  cardsData.forEach((data, i) => {
    const cardGroup = new THREE.Object3D();
    cardGroup.name = `feature-card-${i}`;
    const x = startX + i * (cardW + gap);
    cardGroup.position.set(x, 0, 0);

    // card body material - vertical gradient with hairline border
    const topColor = color('#191921');
    const bottomColor = color('#121218');
    const vGrad = mix(topColor, bottomColor, uv().y);
    const cardMat = new THREE.MeshStandardNodeMaterial();
    cardMat.colorNode = vGrad;
    cardMat.roughness = 0.6;
    cardMat.metalness = 0.25;
    cardMat.clearcoat = 0.15;
    disposables.push(cardMat);

    const cardMesh = new THREE.Mesh(cardGeo, cardMat);
    cardMesh.position.z = 0;
    cardGroup.add(cardMesh);

    // hairline border
    const borderGeo = new THREE.EdgesGeometry(cardGeo);
    disposables.push(borderGeo);
    const borderMat = new THREE.LineBasicNodeMaterial({ color: 0x26262f });
    disposables.push(borderMat);
    const border = new THREE.LineSegments(borderGeo, borderMat);
    border.position.z = 0.001;
    cardGroup.add(border);

    // contact shadow
    const shadowGeo = new THREE.PlaneGeometry(cardW * 1.1, 0.15);
    disposables.push(shadowGeo);
    const shadowMat = new THREE.MeshBasicNodeMaterial({
      color: 0x000000,
      transparent: true,
      opacity: 0.35
    });
    disposables.push(shadowMat);
    const shadow = new THREE.Mesh(shadowGeo, shadowMat);
    shadow.position.set(0, -cardH / 2 - 0.02, -0.01);
    shadow.rotation.x = 0;
    cardGroup.add(shadow);

    // icon seat disc
    const discMat = new THREE.MeshStandardNodeMaterial();
    discMat.color = new THREE.Color('#1c1c24');
    discMat.roughness = 0.55;
    discMat.metalness = 0.5;
    discMat.clearcoat = 0.2;
    disposables.push(discMat);
    const disc = new THREE.Mesh(discGeo, discMat);
    disc.rotation.x = Math.PI / 2;
    const topPad = 0.375;
    const discY = cardH / 2 - topPad - 0.2;
    disc.position.set(0, discY, 0.04);
    cardGroup.add(disc);

    // glyph text on disc
    const glyphText = ctx.fontAtlas.createText(data.glyph, {
      font: 'JetBrains Mono',
      fontSize: 20,
      fontWeight: 700,
      color: '#ff2a38',
      emissiveIntensity: 1.6,
      anchor: 'center'
    });
    glyphText.position.set(0, discY, 0.07);
    glyphText.userData.baseEmissive = 1.6;
    cardGroup.add(glyphText);

    // title text
    const titleY = discY - 0.2 - 0.25;
    const titleText = ctx.fontAtlas.createText(data.title, {
      font: 'Lora',
      fontSize: 20,
      fontWeight: 600,
      color: '#e8ecf2',
      maxWidth: cardW - 0.75,
      anchor: 'top-center'
    });
    titleText.position.set(0, titleY, 0.03);
    cardGroup.add(titleText);

    // body text
    const bodyY = titleY - 0.34 - 0.125;
    const bodyText = ctx.fontAtlas.createText(data.body, {
      font: 'JetBrains Mono',
      fontSize: 13,
      fontWeight: 400,
      color: '#e8ecf2',
      maxWidth: cardW - 0.75,
      lineHeight: 1.5,
      anchor: 'top-center'
    });
    bodyText.position.set(0, bodyY, 0.03);
    cardGroup.add(bodyText);

    cardGroup.userData.glyphText = glyphText;
    cardGroup.userData.discMat = discMat;
    cardGroup.userData.shadow = shadow;
    cardGroup.userData.shadowMat = shadowMat;
    cardGroup.userData.baseY = 0;

    group.add(cardGroup);
    cardObjects.push(cardGroup);
  });

  // stagger-cards fade-up mount animation
  cardObjects.forEach((cardGroup, i) => {
    gsap.set(cardGroup, { y: 0.2 });
    gsap.set(cardGroup.children, { });
    cardGroup.userData.opacity = 0;
    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.fromTo(
      cardGroup.position,
      { y: 0.2 },
      { y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }
    );
    timelines.push(tl);
  });

  // hover lift handlers
  function onHoverStart(cardGroup) {
    const tl = gsap.timeline();
    tl.to(cardGroup.position, {
      y: 0.06,
      z: 0.12,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }, 0);
    tl.to(cardGroup.userData.glyphText.material || {}, {}, 0); // placeholder no-op safe
    if (cardGroup.userData.glyphText.userData) {
      const glyph = cardGroup.userData.glyphText;
      gsap.to({ v: glyph.userData.baseEmissive || 1.6 }, {
        v: 2.2,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        onUpdate: function () {
          if (glyph.material && glyph.material.emissiveIntensity !== undefined) {
            glyph.material.emissiveIntensity = this.targets()[0].v;
          }
        }
      });
    }
    gsap.to(cardGroup.userData.shadow.scale, { x: 1.15, y: 1.3, duration: 0.18 });
    gsap.to(cardGroup.userData.shadowMat, { opacity: 0.2, duration: 0.18 });
    timelines.push(tl);
  }

  function onHoverEnd(cardGroup) {
    const tl = gsap.timeline();
    tl.to(cardGroup.position, {
      y: 0,
      z: 0,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }, 0);
    const glyph = cardGroup.userData.glyphText;
    gsap.to({ v: 2.2 }, {
      v: 1.6,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      onUpdate: function () {
        if (glyph.material && glyph.material.emissiveIntensity !== undefined) {
          glyph.material.emissiveIntensity = this.targets()[0].v;
        }
      }
    });
    gsap.to(cardGroup.userData.shadow.scale, { x: 1, y: 1, duration: 0.18 });
    gsap.to(cardGroup.userData.shadowMat, { opacity: 0.35, duration: 0.18 });
    timelines.push(tl);
  }

  group.userData.handlers = {
    onPointerOver: (intersect) => {
      const cardGroup = cardObjects.find(c => c === intersect?.object?.parent || c.children.includes(intersect?.object));
      if (cardGroup) onHoverStart(cardGroup);
    },
    onPointerOut: (intersect) => {
      const cardGroup = cardObjects.find(c => c === intersect?.object?.parent || c.children.includes(intersect?.object));
      if (cardGroup) onHoverEnd(cardGroup);
    }
  };

  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    disposables.forEach(d => d.dispose && d.dispose());
    cardObjects.forEach(cardGroup => {
      if (cardGroup.userData.glyphText?.userData?.dispose) cardGroup.userData.glyphText.userData.dispose();
      if (cardGroup.userData.titleText?.userData?.dispose) cardGroup.userData.titleText.userData.dispose();
      if (cardGroup.userData.bodyText?.userData?.dispose) cardGroup.userData.bodyText.userData.dispose();
    });
  };

  return group;
}
